export const duration=34;
export const config={title:'混合接合',sceneLabel:'兩片晶圓的SiO₂先預接合，退火後形成Cu對Cu電氣連接',question:'同一界面，兩種材料接合',overview:29,notes:['採 wafer-to-wafer Cu／SiO₂ 代表模型。從已完成元件、平坦化及清潔的晶圓開始；先表面準備與活化，翻面對準，室溫介電預接合，再退火強化介電接合並完成銅接點。','上片繞水平軸翻面，以剖面厚度的縮短與翻轉表示，不交換左右接點。金色角標與既有導線跟隨上片；兩對銅墊在對準後才靠近。銅表面受控凹陷極度放大，並非實際尺寸。','介電接合前緣用綠色界面線表示，此線不是新增膠層。退火期間銅保持固態；以凹陷逐步閉合表示定性接點形成，不計算熱膨脹、原子擴散或表面化學。電路路徑僅在接點完成後顯示。','不含焊球、熔融液滴或導電膠；不重作前段製程、SOI轉移。imec的Cu／SiCN研究只用於表面及凹陷原理，不挪用其間距、溫度或性能數字。'],sources:[['EV Group：介電預接合與退火金屬接合','https://www.evgroup.com/technologies/fusion-and-hybrid-bonding/'],['imec：平坦表面、銅凹陷、中心向外接合波','https://www.imec-int.com/en/articles/wafer-wafer-hybrid-bonding-pushing-boundaries-400nm-interconnect-pitch']]};
export const steps=[{end:5,title:'表面準備',key:3.5,what:'兩片晶圓已平坦化、清潔，進行表面活化。銅墊相對SiO₂略微凹陷。',detail:'本圖凹陷高度大幅放大；沒有新增焊料或膠。'}, {end:10,title:'上片翻面',key:8.5,what:'上片繞水平軸翻轉，讓兩個接合面相向。',detail:'角標及外接線跟著同一片晶圓；左右接點沒有鏡射交換。'}, {end:14,title:'精確對準',key:13.5,what:'上片橫向移動，使兩對銅墊與相鄰介電區對準。',detail:'對位標記先重合，尚未接觸也未導通。'}, {end:22,title:'介電預接合',key:20,what:'兩面靠近，在室溫由中央向外形成介電預接合。',detail:'綠色線代表已接合界面；銅墊仍有凹陷間隙，不能提前宣稱電性接通。'}, {end:28,title:'退火完成接點',key:26,what:'退火強化介電接合，銅的凹陷間隙逐步閉合，形成固態金屬接合。',detail:'銅不熔化、不變成液滴；相鄰絕緣區仍隔開兩組接點。'}, {end:31,title:'連通路徑',key:29,what:'沿第一對銅接點顯示上下導線的連通。',detail:'這是示意路徑，不是實際量測的電流或良率。'}, {end:34,title:'接合晶圓對移交',key:31.2,what:'已接合的晶圓對整組離開，下一輪由新的一對進場。',detail:'完成接點不自行拆開。'}];
export const ramp=(t,a,b)=>Math.max(0,Math.min(1,(t-a)/(b-a)));export const ease=x=>x*x*(3-2*x);
export function stateAt(t){t=Math.max(0,Math.min(duration-.0001,t));const index=steps.findIndex(s=>t<s.end);return {t,index,step:steps[index],flip:ease(ramp(t,5,9)),align:ease(ramp(t,10,13)),approach:ease(ramp(t,14,18)),bond:ramp(t,18,21.5),anneal:ramp(t,22.5,27.5),connected:t>=28,entry:ease(ramp(t,0,1)),exit:ease(ramp(t,31.5,33.5))};}
